-- WF-045: durable owner-only notices generated by committed backend events.
-- Event IDs, optional preferences and acknowledgement state stay in Supabase.
create table public.private_notifications (
  id uuid primary key default gen_random_uuid(),
  owner_user_id uuid not null references auth.users(id) on delete cascade,
  event_type text not null check (event_type in (
    'ACCOUNT_EXIT_REQUESTED','MODERATION_OPENED','MODERATION_DECIDED','MODERATION_HOLD_LIFTED',
    'PORTFOLIO_MODERATION_BLOCKED',
    'REVIEWER_GRANT_ISSUED','REVIEWER_GRANT_REVOKED','RELEASE_VERIFIED','CLOUD_REVISION_SAVED'
  )),
  category text not null check (category in ('SECURITY','MODERATION','REVIEWER','PUBLISH','SYNC')),
  priority text not null check (priority in ('HIGH','NORMAL')),
  target_id uuid not null,
  source_key text not null,
  created_at timestamptz not null default statement_timestamp(),
  read_at timestamptz,
  dismissed_at timestamptz,
  unique(owner_user_id,event_type,source_key),
  check (dismissed_at is null or read_at is not null)
);
create index kd_owner_notifications_inbox on public.private_notifications
  (owner_user_id,created_at desc,id desc) where dismissed_at is null;
alter table public.private_notifications enable row level security;
revoke all on public.private_notifications from public,anon,authenticated,service_role;
grant select (id,owner_user_id,event_type,category,priority,target_id,created_at,read_at,dismissed_at)
  on public.private_notifications to authenticated;
create policy kd_notifications_owner_read on public.private_notifications
  for select to authenticated using ((select auth.uid())=owner_user_id);

create table public.private_notification_preferences (
  owner_user_id uuid primary key references auth.users(id) on delete cascade,
  reviewer_enabled boolean not null default true,
  publish_enabled boolean not null default true,
  sync_enabled boolean not null default false
);
alter table public.private_notification_preferences enable row level security;
revoke all on public.private_notification_preferences from public,anon,authenticated,service_role;
grant select on public.private_notification_preferences to authenticated;
create policy kd_notification_preferences_owner_read on public.private_notification_preferences
  for select to authenticated using ((select auth.uid())=owner_user_id);

create function public.owner_set_notification_preferences(
  p_reviewer_enabled boolean,p_publish_enabled boolean,p_sync_enabled boolean
) returns public.private_notification_preferences
language plpgsql security definer set search_path=''
as $function$
declare
  v_owner uuid := (select auth.uid());
  v_row public.private_notification_preferences;
begin
  perform kadmeion_private.require_live_exit_auth_session();
  if p_reviewer_enabled is null or p_publish_enabled is null or p_sync_enabled is null then
    raise exception using errcode='22023',message='NOTIFICATION_PREFERENCES_REQUIRED';
  end if;
  insert into public.private_notification_preferences (
    owner_user_id,reviewer_enabled,publish_enabled,sync_enabled
  ) values (v_owner,p_reviewer_enabled,p_publish_enabled,p_sync_enabled)
  on conflict (owner_user_id) do update set
    reviewer_enabled=excluded.reviewer_enabled,
    publish_enabled=excluded.publish_enabled,
    sync_enabled=excluded.sync_enabled
  returning * into v_row;
  return v_row;
end;
$function$;

create function public.owner_acknowledge_notification(p_id uuid,p_dismiss boolean default false)
returns jsonb language plpgsql security definer set search_path=''
as $function$
declare
  v_owner uuid := (select auth.uid());
  v_row public.private_notifications;
begin
  perform kadmeion_private.require_live_exit_auth_session();
  if p_id is null or p_dismiss is null then
    raise exception using errcode='22023',message='INVALID_NOTIFICATION_ACTION';
  end if;
  update public.private_notifications
  set read_at=coalesce(read_at,statement_timestamp()),
      dismissed_at=case when p_dismiss then coalesce(dismissed_at,statement_timestamp()) else dismissed_at end
  where id=p_id and owner_user_id=v_owner
  returning * into v_row;
  if not found then
    raise exception using errcode='42501',message='NOTIFICATION_NOT_FOUND';
  end if;
  return jsonb_build_object('id',v_row.id,'read_at',v_row.read_at,'dismissed_at',v_row.dismissed_at);
end;
$function$;
revoke all on function public.owner_set_notification_preferences(boolean,boolean,boolean),
  public.owner_acknowledge_notification(uuid,boolean) from public,anon,authenticated,service_role;
grant execute on function public.owner_set_notification_preferences(boolean,boolean,boolean),
  public.owner_acknowledge_notification(uuid,boolean) to authenticated;

create function kadmeion_private.record_owner_notification()
returns trigger language plpgsql security definer set search_path=''
as $function$
declare
  v_row jsonb := to_jsonb(new);
  v_owner uuid := (v_row->>'owner_user_id')::uuid;
  v_event text;
  v_category text;
  v_target uuid;
  v_source text;
  v_enabled boolean;
begin
  case tg_table_name
    when 'private_account_erasure_requests' then
      v_event:='ACCOUNT_EXIT_REQUESTED';
      v_category:='SECURITY';
      v_target:=(v_row->>'id')::uuid;
      v_source:=(v_row->>'id');
    when 'private_moderation_events' then
      v_event:=case v_row->>'event_type'
        when 'OPENED' then 'MODERATION_OPENED'
        when 'OPERATOR_DECISION' then 'MODERATION_DECIDED'
        when 'OPERATOR_HOLD_LIFT' then 'MODERATION_HOLD_LIFTED'
      end;
      if v_event is null then return null; end if;
      v_category:='MODERATION';
      v_target:=(v_row->>'case_id')::uuid;
      v_source:=(v_row->>'id');
    when 'private_reviewer_grants' then
      v_event:=case when tg_op='INSERT' then 'REVIEWER_GRANT_ISSUED' else 'REVIEWER_GRANT_REVOKED' end;
      v_category:='REVIEWER';
      v_target:=(v_row->>'portfolio_id')::uuid;
      v_source:=(v_row->>'id');
    when 'private_release_visibility_events' then
      v_event:='PORTFOLIO_MODERATION_BLOCKED';
      v_category:='MODERATION';
      v_target:=(v_row->>'portfolio_id')::uuid;
      v_source:=(v_row->>'id');
    when 'verified_unlisted_releases' then
      v_event:='RELEASE_VERIFIED';
      v_category:='PUBLISH';
      v_target:=(v_row->>'portfolio_id')::uuid;
      v_source:=(v_row->>'intent_id');
    when 'portfolio_revisions' then
      v_event:='CLOUD_REVISION_SAVED';
      v_category:='SYNC';
      v_target:=(v_row->>'portfolio_id')::uuid;
      v_source:=(v_row->>'portfolio_id')||':'||(v_row->>'revision');
    else
      raise exception 'Unexpected notification event source';
  end case;
  if v_category in ('REVIEWER','PUBLISH','SYNC') then
    select case v_category
        when 'REVIEWER' then p.reviewer_enabled
        when 'PUBLISH' then p.publish_enabled
        else p.sync_enabled
      end into v_enabled
      from public.private_notification_preferences p where p.owner_user_id=v_owner;
    if not coalesce(v_enabled,v_category<>'SYNC') then return null; end if;
  end if;
  insert into public.private_notifications (
    owner_user_id,event_type,category,priority,target_id,source_key
  ) values (
    v_owner,v_event,v_category,
    case when v_category in ('SECURITY','MODERATION') then 'HIGH' else 'NORMAL' end,
    v_target,v_source
  ) on conflict (owner_user_id,event_type,source_key) do nothing;
  return null;
end;
$function$;
revoke all on function kadmeion_private.record_owner_notification()
  from public,anon,authenticated,service_role;

create trigger kd_account_exit_notification after insert on public.private_account_erasure_requests
  for each row execute function kadmeion_private.record_owner_notification();
create trigger kd_moderation_notification after insert on public.private_moderation_events
  for each row execute function kadmeion_private.record_owner_notification();
create trigger kd_moderation_block_notification after insert on public.private_release_visibility_events
  for each row when (new.event_type='OPERATOR_BLOCK')
  execute function kadmeion_private.record_owner_notification();
create trigger kd_reviewer_issued_notification after insert on public.private_reviewer_grants
  for each row execute function kadmeion_private.record_owner_notification();
create trigger kd_reviewer_revoked_notification after update of revoked_at on public.private_reviewer_grants
  for each row when (old.revoked_at is null and new.revoked_at is not null)
  execute function kadmeion_private.record_owner_notification();
create trigger kd_release_verified_notification after insert on public.verified_unlisted_releases
  for each row execute function kadmeion_private.record_owner_notification();
create trigger kd_cloud_revision_notification after insert on public.portfolio_revisions
  for each row execute function kadmeion_private.record_owner_notification();
